"""
Mysenvar common helpers

The one place for things every Encyclopedia program needs to agree on:
where the vault and the metadata database are, how the calendar works, and
how dates are read and written.

Programs load it with these lines at the top (they work from any folder):

    import sys, pathlib
    sys.dont_write_bytecode = True
    for _p in pathlib.Path(__file__).resolve().parents:
        if (_p / "Meta/Programs/mysenvar_common.py").is_file():
            sys.path.insert(0, str(_p / "Meta/Programs")); break
    import mysenvar_common as mc

and then use mc.VAULT, mc.load_metadata(), mc.year_link(-177), and so on.

To point every program at a different copy of the vault (for testing), set
the environment variable MYSENVAR_VAULT to that folder.
"""
import json
import os
import pathlib
import re

# =============================================================================
#  Where things are
# =============================================================================
# This file lives at <vault>/Meta/Programs/, so the vault is two folders up.
# That holds locally, in GitHub Actions (where the vault is `content/`), and
# no matter which folder a program is started from.
VAULT = pathlib.Path(os.environ.get("MYSENVAR_VAULT") or pathlib.Path(__file__).resolve().parents[2])

ENCYCLOPEDIA_REL = "Encyclopedia Mysenvaria"
DECADES_DIR_REL = "Encyclopedia Mysenvaria/Indexes/History/Decades"
CENTURIES_DIR_REL = "Encyclopedia Mysenvaria/Indexes/History/Centuries"
METADATA_DOC_REL = "Meta/Metadata.md"
METADATA_DIR_REL = "Meta/Programs/debug/metadata_aggregator"
METADATA_JSON_REL = METADATA_DIR_REL + "/extracted_metadata.json"
HOME_PAGE_REL = "_index.md"

ENCYCLOPEDIA = VAULT / ENCYCLOPEDIA_REL
DECADES_DIR = VAULT / DECADES_DIR_REL
CENTURIES_DIR = VAULT / CENTURIES_DIR_REL
METADATA_DOC = VAULT / METADATA_DOC_REL
METADATA_DIR = VAULT / METADATA_DIR_REL
METADATA_JSON = VAULT / METADATA_JSON_REL
HOME_PAGE = VAULT / HOME_PAGE_REL
PROGRAMS = VAULT / "Meta/Programs"
PRIVATE = VAULT / "Private"

# =============================================================================
#  The calendar
# =============================================================================
DAYS_PER_YEAR = 360
SEASON_LENGTH = 90
SEASONS = ["Spring", "Summer", "Autumn", "Winter"]

# (name, first year, last year); None = still going. BT years are negative.
ERAS = [
    ("God-War Era", -177, -1),
    ("Post-War Era", 0, 608),
    ("Golden Age", 609, 1213),
    ("Modern Era", 1214, None),
]

# The span of history that gets decade pages.
FIRST_YEAR = -178
LAST_YEAR = 1499


def ordinal(n):
    """1 -> '1st', 2 -> '2nd', 11 -> '11th', 23 -> '23rd'."""
    n = int(n)
    if 11 <= (n % 100) <= 13:
        return f"{n}th"
    return f"{n}" + {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th")


def era_of(year):
    """The era a year falls in, or None (before the God-War)."""
    for name, first, last in ERAS:
        if year >= first and (last is None or year <= last):
            return name
    return None


def year_suffix(year):
    """-177 -> '177 BT', 0 -> '0 AT'."""
    return f"{abs(year)} BT" if year < 0 else f"{year} AT"


def season_day(day):
    """Day of the year (1-360) -> '59th of Winter'."""
    idx = (day - 1) // SEASON_LENGTH
    return f"{ordinal(day - idx * SEASON_LENGTH)} of {SEASONS[idx]}"

# =============================================================================
#  Dates
# =============================================================================
def split_date(value):
    """
    Read a date written any accepted way and return (year, day, problem).
    day is None for year-only dates; problem is None when the date is fine,
    "empty" for [] or "", or a short explanation otherwise.

    Accepts [year], [year, day], a year number, "year-day" / "year,day",
    {"year": .., "day": ..}, and the aggregator's normalised dates.
    """
    if isinstance(value, dict) and "original" in value:
        value = value["original"]
    try:
        if isinstance(value, bool):
            return None, None, "is true/false, not a date"
        if isinstance(value, (list, tuple)):
            if len(value) == 0:
                return None, None, "empty"
            if len(value) > 2:
                return None, None, f"has {len(value)} parts; use [year] or [year, day]"
            y = int(value[0])
            d = int(value[1]) if len(value) > 1 and value[1] is not None else None
        elif isinstance(value, dict):
            if "year" not in value:
                return None, None, "has no `year`"
            y = int(value["year"])
            d = int(value["day"]) if value.get("day") is not None else None
        elif isinstance(value, (int, float)):
            if isinstance(value, float) and not value.is_integer():
                return None, None, "year isn't a whole number"
            y, d = int(value), None
        elif isinstance(value, str):
            clean = value.strip("'\" []")
            if not clean:
                return None, None, "empty"
            m = re.fullmatch(r"\s*([+-]?\d+)\s*(?:[,\-]\s*(\d+))?\s*", clean)
            if not m:
                return None, None, f"`{value}` can't be read as a date"
            y = int(m.group(1))
            d = int(m.group(2)) if m.group(2) else None
        elif value is None:
            return None, None, "empty"
        else:
            return None, None, f"unexpected value `{value}`"
    except (TypeError, ValueError):
        return None, None, f"`{value}` can't be read as a date"
    if d is not None and not (1 <= d <= DAYS_PER_YEAR):
        return y, d, f"day {d} is outside 1-{DAYS_PER_YEAR}"
    return y, d, None


def year_day(value):
    """(year, day) of any date, or (None, None) if it can't be read."""
    y, d, problem = split_date(value)
    return (None, None) if problem else (y, d)


def normalise_date(value):
    """
    The aggregator's date object. Everything a program or an index might want to read from a date is a field
    of its own, so an index can point straight at it (`star[].publications[0].date.year`):
        {"original": [-178, 329],          the date as written on the page
         "year": -178, "day": 329,          day is null for a year-only date
         "season": "Winter", "season_day": 59,
         "era": "BT",
         "decade": "170s BT", "century": "2nd Century BT",
         "sort": -177671,                   one number that runs in time order (year * 1000 + day)
         "formal": "59th of Winter, 178 BT",
         "formal_without_year": "59th of Winter",
         "informal": "-178-329"}
    Returns None if the date can't be read. An already-normalised date is rebuilt from its `original`.
    """
    if isinstance(value, dict) and "original" in value:
        value = value["original"]
    y, d, problem = split_date(value)
    if problem:
        return None
    era = "AT" if y >= 0 else "BT"
    out = {"original": value, "year": y, "day": d, "season": None, "season_day": None, "era": era,
           "decade": decade_title(y), "century": century_title(*century_of(y)), "sort": y * 1000 + (d or 0)}
    if d is not None:
        sd = season_day(d)
        idx = (d - 1) // SEASON_LENGTH
        out.update(season=SEASONS[idx], season_day=d - idx * SEASON_LENGTH,
                   formal=f"{sd}, {abs(y)} {era}", formal_without_year=sd, informal=f"{y}-{d}")
    else:
        out.update(formal=f"{abs(y)} {era}", formal_without_year="", informal=f"{y}")
    return out


def century_of(year):
    """The century a year is in, as (number, era): -178 -> (2, "BT"), -100 -> (1, "BT"), 1496 -> (15, "AT")."""
    if year < 0:
        return (-year + 99) // 100, "BT"
    return year // 100 + 1, "AT"


def date_sort_value(value):
    """A number that sorts dates chronologically (year-only dates first in their year)."""
    y, d = year_day(value)
    return None if y is None else y * 1000 + (d or 0)


def format_date(value):
    """'59th of Winter, 178 BT', or '178 BT' for year-only dates; '' if unreadable."""
    y, d = year_day(value)
    if y is None:
        return ""
    return f"{season_day(d)}, {year_suffix(y)}" if d else year_suffix(y)

# =============================================================================
#  Decades and centuries
# =============================================================================
def decade_key(year):
    """The decade a year belongs to as (era, start), e.g.
    177 BT -> ("BT", 170), 5 BT -> ("BT", 0), 0 AT -> ("AT", 0), 1313 AT -> ("AT", 1310).
    BT decades count away from the Treaty, so the 170s BT are 170-179 BT."""
    if year < 0:
        return ("BT", (abs(year) // 10) * 10)
    return ("AT", (year // 10) * 10)


def decade_sort_value(key):
    """Chronological sort value for a decade key (earliest first)."""
    era, start = key
    return -(start + 10) if era == "BT" else start


def decade_title(key_or_year):
    """("BT", 170) or -177 -> '170s BT'."""
    era, start = decade_key(key_or_year) if isinstance(key_or_year, int) else key_or_year
    return f"{start}s {era}"


def all_decades():
    """Every decade from FIRST_YEAR to LAST_YEAR, earliest first."""
    return sorted({decade_key(y) for y in range(FIRST_YEAR, LAST_YEAR + 1)}, key=decade_sort_value)


def century_title(val, suffix):
    """(2, 'BT') -> '2nd Century BT'."""
    return f"{ordinal(val)} Century {suffix}"


def century_bounds(val, suffix):
    """(first year, last year) of an ordinal century.
    1st BT: -100 to -1, 2nd BT: -200 to -101; 1st AT: 0 to 99, 2nd AT: 100 to 199."""
    if suffix == "BT":
        return -(val * 100), -((val - 1) * 100 + 1)
    return (val - 1) * 100, (val * 100) - 1


def year_link(year):
    """-177 -> [[Encyclopedia Mysenvaria/Indexes/History/Decades/170s BT#177 BT|177 BT]]"""
    text = year_suffix(year)
    return f"[[{DECADES_DIR_REL}/{decade_title(decade_key(year))}#{text}|{text}]]"

# =============================================================================
#  The metadata database
# =============================================================================
def load_metadata(path=None):
    """The aggregator's database ({"meta": .., "pages": [..], "issues": [..]}).
    Stops the program with a clear message if the aggregator hasn't been run."""
    path = pathlib.Path(path) if path else METADATA_JSON
    if not path.is_file():
        raise SystemExit(f"[ERROR] {path} not found. Run metadata_aggregator.py first.")
    with open(path, encoding="utf-8") as f:
        return json.load(f)


def load_pages(path=None):
    """Just the list of pages (and subpages) from the database."""
    return load_metadata(path).get("pages", [])


def page_link_path(meta):
    """The link target of a page's `link`, without brackets or display text."""
    link = str(meta.get("link", "")).strip("[]")
    return link.split("|")[0].strip()


def legacy_flat_view(data=None):
    """
    The database in the older flat layout some programs were written for:
        {"event":  [{source, start_date, end_date, start_desc, end_desc, major_event, ...}],
         "person": [{source, title, name, birthday, death_date, spouses, major_event, ...}],
         "star":   {"bases": [{source, star_name, coordinates, desc, orbital}],
                    "publications": [{source, star_name, date, publishers, desc, major_event}],
                    "translations": [{source, star_name, date, translators, desc, major_event}]}}
    Dates come out as {"year": .., "day": ..}. Star coordinates come out as
    "az A, alt B, dist C" text, following the Encyclopedia's (Azimuth, Altitude,
    Distance) order.
    """
    if data is None:
        data = load_metadata()

    def flat_date(v):
        y, d = year_day(v)
        if y is None:
            return None
        return {"year": y, "day": d} if d is not None else {"year": y}

    def coords_text(c):
        if isinstance(c, (list, tuple)) and len(c) == 3:
            return f"az {c[0]}, alt {c[1]}, dist {c[2]}"
        return c if isinstance(c, str) else ""

    out = {"event": [], "person": [], "star": {"bases": [], "publications": [], "translations": []}}
    for page in data.get("pages", []):
        meta = page.get("metadata", {})
        source = page.get("parent") or page.get("src_rel", "")
        title = meta.get("title", "")
        for ev in meta.get("event") or []:
            if isinstance(ev, dict):
                row = dict(ev, source=source, title=title)
                row["start_date"], row["end_date"] = flat_date(ev.get("start_date")), flat_date(ev.get("end_date"))
                out["event"].append(row)
        for p in meta.get("person") or []:
            if isinstance(p, dict):
                row = dict(p, source=source, title=title)
                row["birthday"] = row["birth_date"] = flat_date(p.get("birth_date"))
                row["death_date"] = flat_date(p.get("death_date"))
                row["spouses"] = [dict(s, start_date=flat_date(s.get("start_date")), end_date=flat_date(s.get("end_date")))
                                  for s in (p.get("spouses") or []) if isinstance(s, dict)]
                out["person"].append(row)
        for s in meta.get("star") or []:
            if not isinstance(s, dict):
                continue
            name = s.get("name") or title
            orbital = s.get("orbital")
            if isinstance(orbital, dict) and isinstance(orbital.get("center"), (list, tuple)):
                orbital = dict(orbital, center=coords_text(orbital["center"]))
            out["star"]["bases"].append({"source": source, "star_name": name,
                                         "coordinates": coords_text(s.get("coordinates")),
                                         "desc": s.get("desc", ""), "orbital": orbital})
            for kind in ("publications", "translations"):
                for e in s.get(kind) or []:
                    if isinstance(e, dict):
                        date = flat_date(e.get("date"))
                        if date is not None:
                            out["star"][kind].append(dict(e, source=source, star_name=name, date=date))
    return out

# =============================================================================
#  Page status (scope / progress / future)
# =============================================================================
# The values themselves are documented in Meta/Metadata.md (the aggregator reads
# its allowed lists from there); these are the fallbacks and the order of the ladder.
SCOPES = ["brief", "standard", "overview", "generated"]
PROGRESSES = ["empty", "idea", "wip", "stub", "complete"]   # least to most finished
FUTURES = ["pending", "rewrite", "review"]
STATUS_DEFAULTS = {"scope": "brief", "progress": "empty", "future": []}
# Page types that carry a `status` block (see Meta/Metadata.md).
STATUS_TYPES = {"article", "index", "addenda", "canvas", "template"}

# The old one-line `status:` / `future:` values and what they became.
OLD_STATUS_TO_PROGRESS = {"empty": "empty", "stub": "stub", "incomplete": "wip", "complete": "complete"}
OLD_FUTURE_TO_FUTURE = {"none": [], "": [], "update": ["pending"], "rewrite": ["rewrite"], "review": ["review"],
                        "auto-generated": []}


def convert_old_status(status, future, page_type, default_scope="standard"):
    """Old `status` / `future` / `type` values -> (new status block, new type).
    `type: overview` becomes `type: article` with `scope: overview`, and
    `future: auto-generated` becomes `scope: generated`."""
    status = str(status or "empty").strip().lower()
    future = str(future or "none").strip().lower()
    page_type = str(page_type or "article").strip().lower()
    scope = default_scope
    if page_type == "overview":
        page_type, scope = "article", "overview"
    if future == "auto-generated":
        scope = "generated"
    block = {"scope": scope,
             "progress": OLD_STATUS_TO_PROGRESS.get(status, status),
             "future": list(OLD_FUTURE_TO_FUTURE.get(future, [future]))}
    return block, page_type


def as_future_list(value):
    """`future` as a list, whether it was written as a list, one value, or left out."""
    if value is None or value == "" or value == "none":
        return []
    if isinstance(value, (list, tuple)):
        return [str(v).strip() for v in value if str(v).strip() and str(v).strip() != "none"]
    return [str(value).strip()]


def status_of(meta, parent_status=None):
    """A page's (or subpage's) status block with defaults filled in:
    {"scope": .., "progress": .., "future": [..]}. Subpages take any missing
    keys from their parent's block. Old one-line values are converted."""
    raw = meta.get("status")
    if isinstance(raw, dict):
        block = dict(raw)
    elif raw is not None or "future" in meta:
        block, _ = convert_old_status(raw, meta.get("future"), meta.get("type"))
    else:
        block = {}
    base = dict(parent_status) if parent_status else dict(STATUS_DEFAULTS)
    for k in ("scope", "progress", "future"):
        if k not in block or block[k] is None:
            block[k] = base.get(k, STATUS_DEFAULTS[k])
    block["future"] = as_future_list(block["future"])
    return block


def read_status_text(text, indent=0):
    """
    Read a status block straight from front-matter text, without a YAML library
    (for programs that read pages directly, like the print compiler).
    `indent` is the indentation of the `status:` key (0 for a page, more inside a
    subpage). Returns the block like status_of(), or None if there's no status at all.
    Old one-line `status:` / `future:` values are converted.
    """
    pad = " " * indent
    lines = text.expandtabs(4).splitlines()
    found, block, old_status, old_future, page_type = False, {}, None, None, None
    i = 0
    while i < len(lines):
        ln = lines[i]
        m = re.match(rf"^{pad}(status|future|type):[ \t]*(.*?)\s*(?:#.*)?$", ln)
        if m and (len(ln) - len(ln.lstrip(" "))) == indent:
            key, val = m.group(1), m.group(2).strip().strip('"').strip("'")
            if key == "type":
                page_type = val
            elif key == "future":
                old_future, found = val, True
            elif val:                       # old one-line `status: complete`
                old_status, found = val, True
            else:                           # the new block: read the indented lines under it
                found = True
                j = i + 1
                while j < len(lines) and (not lines[j].strip() or len(lines[j]) - len(lines[j].lstrip(" ")) > indent):
                    sub = re.match(r"^\s+(scope|progress|future):[ \t]*(.*?)\s*(?:#.*)?$", lines[j])
                    if sub:
                        k, v = sub.group(1), sub.group(2).strip()
                        if k == "future":
                            if v.startswith("["):
                                block[k] = [x.strip().strip('"').strip("'") for x in v.strip("[]").split(",") if x.strip()]
                            elif v:
                                block[k] = [v.strip('"').strip("'")]
                            else:            # a block list on the following lines
                                items = []
                                while j + 1 < len(lines) and re.match(r"^\s+-\s+", lines[j + 1]):
                                    j += 1
                                    items.append(re.sub(r"^\s+-\s+", "", lines[j]).strip().strip('"').strip("'"))
                                block[k] = items
                        else:
                            block[k] = v.strip('"').strip("'")
                    j += 1
                i = j - 1
        i += 1
    if not found:
        return None
    if old_status is not None or (old_future is not None and not block):
        return status_of({"status": old_status, "future": old_future, "type": page_type})
    return status_of({"status": block})
